import { Meta, StoryObj } from "@storybook/react";
import { expect, waitFor, within } from "storybook/test";
import { InputError } from "./input-error";
import { VALIDATION_TYPES, ValidationType } from "@/core/helpers/form-builder";
import { ShowcaseLayout, Variant, showcaseParameters } from "@/storybook/preview";

/** The validation types that InputError has a dedicated fallback message for. */
const validationTypesWithMessage = ["EMAIL", "PHONE", "ZIPCODE", "BIRTHDATE", "DATE"] satisfies Array<ValidationType>;

const meta = {
  title: "Primitives/Form Fields/Input Error",
  component: InputError,
  parameters: {
    docs: {
      description: {
        component:
          "Animated error message shown below a form field, with an icon and a text colored by `errorLevel`. " +
          "The message is resolved in priority order: an explicit `errorText`, else a message specific to the " +
          '`validationType` (EMAIL, PHONE, ZIPCODE, BIRTHDATE or DATE), else the generic "required" message ' +
          "when `isRequired` is set. The component renders nothing at all unless `showError` is true and a " +
          "message could be resolved, so a field without any of these props stays silent even in an error state.",
      },
    },
  },
  argTypes: {
    validationType: { options: [undefined, ...Object.values(VALIDATION_TYPES)] },
    "data-testid": { table: { disable: true } },
  },
  args: {
    showError: true,
    isRequired: true,
    errorText: "Vänligen ange ett giltigt telefonnummer",
    validationType: undefined,
    errorLevel: "error",
  },
} satisfies Meta<typeof InputError>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {
  args: { id: "phone-error" },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    // The box animates in via framer-motion (opacity starts at 0), so retry until visible.
    await waitFor(() => {
      expect(canvas.getByText("Vänligen ange ett giltigt telefonnummer")).toBeVisible();
    });
  },
};

export const VariantMessages: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout title="Message resolution (errorText > validationType > isRequired)" variantType="other">
      <Variant label="explicit errorText">
        <InputError {...args} errorText="Det här meddelandet kommer från errorText" />
      </Variant>
      {validationTypesWithMessage.map((validationType) => (
        <Variant key={validationType} label={`validationType ${validationType}, no errorText`}>
          <InputError {...args} errorText={undefined} validationType={validationType} />
        </Variant>
      ))}
      <Variant label="isRequired only (no errorText, no validationType)">
        <InputError {...args} errorText={undefined} validationType={undefined} isRequired />
      </Variant>
      <Variant label="nothing resolvable (renders nothing)">
        <InputError {...args} errorText={undefined} validationType={undefined} isRequired={false} />
      </Variant>
    </ShowcaseLayout>
  ),
};

export const VariantErrorLevel: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout title="errorLevel" variantType="prop">
      <Variant label="error (red icon and text)">
        <InputError {...args} errorLevel="error" />
      </Variant>
      <Variant label="warning (warning icon, black text)">
        <InputError {...args} errorLevel="warning" />
      </Variant>
    </ShowcaseLayout>
  ),
};
